[et_pb_section fb_built="1" admin_label="RM CTA Plan Editorial" _builder_version="4.27.4" use_custom_width="on" width_unit="off" custom_width_px="100%" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_row _builder_version="4.27.4" width="100%" max_width="100%" use_custom_gutter="on" gutter_width="1" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_column type="4_4" _builder_version="4.27.4" global_colors_info="{}"][et_pb_code admin_label="RM CTA Plan Editorial — Code" _builder_version="4.27.4" global_colors_info="{}"]<!-- ============================================================
     RM CTA PLAN EDITORIAL — Bloque 6 "CTA final" del Plan Editorial
     Anual (Divi 5, Code Module)
     Marca: Rodmedia · Reestructuración web
     Cierra la página del Plan Editorial Anual. Vuelve al fondo oscuro
     con el degradado de marca y la línea superior con brillo del
     hero — mismo tratamiento, para que la página empiece y termine
     igual.

     Más simple que los CTA finales de Diseño Web y Tienda Online: me
     diste un único botón ("Pide tu plan editorial") y un texto de
     apoyo, sin segundo CTA de WhatsApp, sin línea de confianza y sin
     tarjetas de "también te puede interesar" — así que esta versión
     no las lleva, para no añadir contenido que no me diste. Si más
     adelante quieres el mismo tratamiento completo que los otros CTA
     (WhatsApp, línea de confianza, tarjetas cruzadas a Blog/SEO/
     Redes sociales), dímelo y lo ampliamos.

     Enlace real ya montado: CTA principal "Pide tu plan editorial" →
     tel:+34691306858 (llama directamente a tu móvil), mismo patrón
     que el resto de CTA finales de la familia. Si prefieres que use
     un calendario de reservas (Calendly, etc.) en vez de llamar
     directo, cambia solo este href.

     id="contacto" en la sección: el hero de esta página ya enlaza su
     CTA secundario a "#contacto" — con este id, aterriza aquí.

     Movimiento (GSAP + ScrollTrigger por CDN, cdnjs): entrada en
     scroll del título/subtítulo, botón y texto de apoyo — mismo
     patrón e instancia compartida que el resto de bloques de esta
     página. Respeta prefers-reduced-motion. El contenido ya es
     visible por CSS si el CDN no carga.

     ANTES DE PUBLICAR:
     1) Si ya cargas Playfair Display / Inter desde el Theme Builder de
        Divi, borra el @import de aquí para evitar cargarlas dos veces.
     ============================================================ -->

<section id="contacto" class="rm-cta-pe" aria-labelledby="rm-cta-pe-title">

  <div class="rm-cta-pe__bg" aria-hidden="true">
    <div class="rm-cta-pe__topline"></div>
    <div class="rm-cta-pe__glow rm-cta-pe__glow--blue"></div>
    <div class="rm-cta-pe__glow rm-cta-pe__glow--orange"></div>
  </div>

  <div class="rm-cta-pe__container">

    <div class="rm-cta-pe__head" data-animate>
      <h2 id="rm-cta-pe-title" class="rm-cta-pe__title">¿Quieres saber qué publicar durante todo el año?</h2>
    </div>

    <div class="rm-cta-pe__actions" data-animate>
      <a href="tel:+34691306858" class="rm-cta-pe__cta rm-cta-pe__cta--primary">
        <span>Pide tu plan editorial</span>
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <path d="M3.5 8h9M8.5 3.5 13 8l-4.5 4.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </a>
    </div>

    <p class="rm-cta-pe__support" data-animate>Cuéntame tu negocio y te propongo qué nivel te encaja.</p>

  </div>
</section>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&family=Inter:wght@400;500;600;700&display=swap');

  .rm-cta-pe {
    --rm-primary: #0f0f1e;
    --rm-blue: #3a7bd5;
    --rm-orange: #e8531a;
    --rm-light: #f8f8fb;
    --rm-text-muted: #9aa3bd;
    --rm-text-muted-2: #7d84a0;
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-transition: 0.3s ease;
    --rm-font-display: "Playfair Display", Georgia, "Times New Roman", serif;
    --rm-font-body: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: var(--rm-primary);
    color: var(--rm-light);
    font-family: var(--rm-font-body);
    padding: 110px 20px 110px;
    box-sizing: border-box;
  }

  .rm-cta-pe *,
  .rm-cta-pe *::before,
  .rm-cta-pe *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo: línea de firma + glows, igual que el hero ---------- */
  .rm-cta-pe__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
  }

  .rm-cta-pe__topline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--rm-blue), var(--rm-orange), var(--rm-blue));
    background-size: 200% 100%;
    animation: rm-cta-pe-shimmer 6s linear infinite;
  }

  @keyframes rm-cta-pe-shimmer {
    0% { background-position: 0% 0; }
    100% { background-position: 200% 0; }
  }

  .rm-cta-pe__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(110px);
    opacity: 0.26;
  }

  .rm-cta-pe__glow--blue {
    width: 480px;
    height: 480px;
    top: -170px;
    left: 50%;
    transform: translateX(-120%);
    background: var(--rm-blue);
  }

  .rm-cta-pe__glow--orange {
    width: 460px;
    height: 460px;
    bottom: -190px;
    left: 50%;
    transform: translateX(20%);
    background: var(--rm-orange);
  }

  @media (prefers-reduced-motion: reduce) {
    .rm-cta-pe__topline {
      animation: none;
    }
  }

  /* ---------- Contenedor ---------- */
  .rm-cta-pe__container {
    position: relative;
    z-index: 1;
    max-width: 580px;
    margin: 0 auto;
    text-align: center;
  }

  /* El contenido se renderiza visible por defecto: si GSAP/ScrollTrigger
     no cargan desde el CDN, nada depende de JS para mostrarse. Cuando
     sí cargan, gsap.from() anima desde un estado inicial oculto hasta
     este estado natural al entrar en scroll — ver el <script> final. */

  .rm-cta-pe__head {
    margin-bottom: 32px;
  }

  .rm-cta-pe__title {
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: clamp(2rem, 1.5rem + 2.4vw, 3rem);
    line-height: 1.16;
    letter-spacing: -0.01em;
    color: var(--rm-light);
    margin: 0;
  }

  /* ---------- Botón ---------- */
  .rm-cta-pe__actions {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 20px;
  }

  .rm-cta-pe__cta {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--rm-font-body);
    font-size: 15.5px;
    font-weight: 600;
    text-decoration: none;
    border-radius: var(--rm-radius);
    padding: 16px 28px;
    transition: transform var(--rm-transition), box-shadow var(--rm-transition);
    overflow: hidden;
  }

  .rm-cta-pe__cta--primary {
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #ffffff;
    box-shadow: 0 12px 28px rgba(58, 123, 213, 0.3);
  }

  .rm-cta-pe__cta--primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(160px circle at var(--rm-mx, 50%) var(--rm-my, 50%), rgba(255, 255, 255, 0.32), transparent 70%);
    opacity: 0;
    transition: opacity var(--rm-transition);
  }

  .rm-cta-pe__cta--primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 34px rgba(232, 83, 26, 0.38);
  }

  .rm-cta-pe__cta--primary:hover::before {
    opacity: 1;
  }

  .rm-cta-pe__cta--primary span,
  .rm-cta-pe__cta--primary svg {
    position: relative;
    z-index: 1;
  }

  .rm-cta-pe__cta svg {
    transition: transform var(--rm-transition);
  }

  .rm-cta-pe__cta--primary:hover svg {
    transform: translateX(3px);
  }

  .rm-cta-pe__cta:focus-visible {
    outline: 2px solid var(--rm-blue);
    outline-offset: 3px;
  }

  /* ---------- Texto de apoyo ---------- */
  .rm-cta-pe__support {
    font-size: 14.5px;
    color: var(--rm-text-muted-2);
    margin: 0;
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 560px) {
    .rm-cta-pe {
      padding: 80px 16px 80px;
    }

    .rm-cta-pe__cta {
      width: 100%;
      justify-content: center;
      text-align: center;
    }
  }
</style>

<script>
  (function () {
    var section = document.querySelector('.rm-cta-pe');
    if (!section) return;

    /* Halo del CTA principal siguiendo al cursor — no necesita GSAP */
    var cta = section.querySelector('.rm-cta-pe__cta--primary');
    if (cta && window.matchMedia('(hover: hover)').matches) {
      cta.addEventListener('mousemove', function (e) {
        var rect = cta.getBoundingClientRect();
        cta.style.setProperty('--rm-mx', (e.clientX - rect.left) + 'px');
        cta.style.setProperty('--rm-my', (e.clientY - rect.top) + 'px');
      });
    }

    /* Carga GSAP + ScrollTrigger por CDN una sola vez por página, aunque
       haya varios bloques de este tipo (reutiliza la instancia si otro
       bloque de esta misma página ya la cargó). */
    function loadScript(src) {
      return new Promise(function (resolve, reject) {
        var existing = document.querySelector('script[data-gsap-src="' + src + '"]');
        if (existing) {
          if (existing.dataset.loaded === 'true') { resolve(); return; }
          existing.addEventListener('load', resolve);
          existing.addEventListener('error', reject);
          return;
        }
        var s = document.createElement('script');
        s.src = src;
        s.dataset.gsapSrc = src;
        s.onload = function () { s.dataset.loaded = 'true'; resolve(); };
        s.onerror = reject;
        document.head.appendChild(s);
      });
    }

    function withGSAP(callback) {
      if (window.gsap && window.ScrollTrigger) { callback(); return; }
      Promise.all([
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js'),
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js')
      ]).then(function () {
        if (window.gsap && window.ScrollTrigger) callback();
      }).catch(function () {
        /* Sin GSAP el contenido ya es visible por CSS: no hace falta nada más. */
      });
    }

    withGSAP(function () {
      gsap.registerPlugin(ScrollTrigger);
      var mm = gsap.matchMedia();

      mm.add('(prefers-reduced-motion: no-preference)', function () {
        var order = ['.rm-cta-pe__head', '.rm-cta-pe__actions', '.rm-cta-pe__support'];
        var tl = gsap.timeline({
          scrollTrigger: { trigger: section, start: 'top 75%', toggleActions: 'play none none reverse' }
        });
        order.forEach(function (sel, i) {
          var el = section.querySelector(sel);
          if (!el) return;
          tl.from(el, {
            y: 20,
            autoAlpha: 0,
            duration: 0.6,
            ease: 'power2.out',
            clearProps: 'transform,opacity,visibility'
          }, i === 0 ? 0 : '-=0.35');
        });
      });
    });
  })();
</script>
[/et_pb_code][/et_pb_column][/et_pb_row][/et_pb_section]
